            D2Win::Src::D2WinTextBox::SetText(*ppSlotTextBox, D2Lang::StrTable::strtable::GetLocaleString(0x1417), 0, false, 0);
            nSlotBoxY += 0x5d;
            nCharIndex = nNavigationIndex;
