BOOL __stdcall CHARSEL_InitRealmSelection() {
    uint16_t* pwszLocaleStr;
    ::D2WinTextBox* pTitleForm;
    int32_t nRegResult;
    uint32_t nTextLine;
    D2BNetGatewayAccessStr* pBNetGateway;
    char* pszRealmName;
    uint16_t wErrorStrId;
    uint8_t nTextArg8;
    gnCharSelBNetLoadState = 0;
    if (OogCurrentCharSelectionMode == CHAR_SELECTION_BNET) {
      MainMenus::MAINMENU_QueryAndBuildRealmList();
      int nRealmCount = MainMenus::MAINMENU_GetRealmCount();
      if (nRealmCount != -1) {
        D2ControlStrc* pTimerForm;
        if (nRealmCount) {
          pTimerForm = MainMenus::FORMS_CreateAnyFormFromListExEx(0x7a);
          D2Win::Src::D2WinTimer::D2WINTIMER_Start((int*)pTimerForm);
          D2Win::Src::D2WinEditBox::D2WINEDITBOX_Destroy((int*)pTimerForm);
          gpCharSelStatusTextBox = (::D2WinTextBox*)MainMenus::FORMS_CreateAnyFormFromListExEx(0x94);
          gnCharSelScrollOffset = (::D2WinTextBox*)MainMenus::FORMS_CreateAnyFormFromListExEx(0x95);
          MainMenus::FORMS_CreateAnyFormFromListExEx(0x69);
          gpControlRealmSelectDropdown = MainMenus::FORMS_CreateAnyFormFromListExEx(0x6b);
          gpControlCharSelList = (::D2WinTextBox*)MainMenus::FORMS_CreateAnyFormFromListExEx(0x6c);
          nRealmCount = 0;
          nTextArg8 = 0;
          nRegResult = 4;
          pwszLocaleStr = D2Lang::StrTable::strtable::GetLocaleString(0x2b32);
          pTitleForm = (::D2WinTextBox*)MainMenus::FORMS_CreateAnyFormFromListExEx(0x6a);
          D2Win::Src::D2WinTextBox::SetText(pTitleForm, pwszLocaleStr, nRegResult, (bool)nTextArg8, nRealmCount);
          nRegResult = Storm::Source::SReg::SRegLoadString("Diablo II", "Preferred Realm", 0, PreferredClosedRealm, 0x100);
          if (nRegResult) {
            nTextLine = CHARSEL_FindRealmByName(PreferredClosedRealm);
            if (nTextLine) {
              return 1;
            }
          }

          pBNetGateway = (D2BNetGatewayAccessStr*)gpBNetCallbacks->pfnBnetLoadAndReturn();
          Storm::Source::SSTR::SStrCopy(PreferredClosedRealm, Bnclient::BNGatewayAccess::Realm(pBNetGateway, pBNetGateway->nCurGatewayIdx), 0x7fffffff);
          Storm::Source::SReg::SRegSaveString("Diablo II", "Preferred Realm", 0, PreferredClosedRealm);
          nTextLine = CHARSEL_FindRealmByName(PreferredClosedRealm);
          if (nTextLine) {
            return 1;
          }

          nRealmCount = MainMenus::MAINMENU_GetRealmCount();
          if (nRealmCount > 0) {
            pszRealmName = MainMenus::MAINMENU_GetRealmName(0);
          } else {
            pszRealmName = 0;
          }

          Storm::Source::SSTR::SStrCopy(PreferredClosedRealm, pszRealmName, 0x7fffffff);
          Storm::Source::SReg::SRegSaveString("Diablo II", "Preferred Realm", 0, PreferredClosedRealm);
          return 1;
        }

        Launcher::LAUNCHER_DisconnectFromBnet();
        wErrorStrId = 0x14aa;
      } else {
        Launcher::LAUNCHER_DisconnectFromBnet();
        wErrorStrId = 0x14e3;
      }

      pwszLocaleStr = D2Lang::StrTable::strtable::GetLocaleString(wErrorStrId);
      MainMenus::MAINMENU_ShowPopupWithCancel(pwszLocaleStr, MainMenus::UIMENU_MainMenu);
      return 0;
    }

    gnCharSelBNetLoadState = 0;
    return 1;
}

// @sourcefile .\Src\CharSel.cpp
int __stdcall CHARSEL_CreateCharEntry(uint16_t * wszCharName, uint16_t * wszCommandString, int32_t nEntryType, uint8_t ePlayerClass) {
    int nAnimMode;
    D2CharSelStrc* pCharSel = D2_NEW_AT(D2CharSelStrc, ".\\Src\\CharSel.cpp", 0xbaf);
    D2Lang::WideCharToUTF8(pCharSel->szCharname, wszCharName, 0x100);
    D2Lang::Unicode::UNISYS::STRING_CopyWideString((uint16_t*)pCharSel->szCommandStringTable, wszCommandString);
    memset(pCharSel->abEquipSlot1, 0, 16 * sizeof(pCharSel->abEquipSlot1[0]));
    memset(pCharSel->abEquipSlot2, 0, 16 * sizeof(pCharSel->abEquipSlot2[0]));
    pCharSel->ePlayerClassID = ePlayerClass;
    pCharSel->nLevel = 0;
    pCharSel->nCharacterFlags = 0;
    pCharSel->nRealmCharCount = 0;
    pCharSel->wEncodedField9 = 0;
    pCharSel->bAct = 0;
    pCharSel->bField_0x32f = 0;
    pCharSel->bField_0x330 = 0;
    pCharSel->pCharSelCompStrc = 0;
    pCharSel->pNext = 0;
    uint8_t* pbEquipPtr = pCharSel->abEquipSlot2;
    int nEquipCounter = 0x10;
    do {
      nAnimMode = nEquipCounter;
      pbEquipPtr[-0x10] = 0;
      *pbEquipPtr = 0xff;
      pbEquipPtr++;
      nEquipCounter = nAnimMode - 1;
    } while (nEquipCounter);

    eD2PlayerClassID ePlayerClassVal = pCharSel->ePlayerClassID;
    pCharSel->abEquipSlot1[1] = 1;
    D2CharSelCompStrc* pCharSelComp = D2Win::Src::D2Comp::AllocCharSelectComponent((uint32_t)ePlayerClassVal, 5, pCharSel->abEquipSlot1, (char*)pCharSel->abEquipSlot2);
    pCharSel->pCharSelCompStrc = pCharSelComp;
    pCharSel->nEntryType = nEntryType;
    D2Win::Src::D2Comp::D2COMP_SetAnimationSpeed(pCharSelComp, 0);
    D2Win::Src::D2Comp::D2COMP_SetCurrentFrame(pCharSel->pCharSelCompStrc, 0);
    D2Win::Src::D2Comp::D2COMP_SetAnimationMode(pCharSel->pCharSelCompStrc, nAnimMode + 4);
    D2CharSelStrc* pListHead = pCharSel;
    if (D2Client::CharScreen::D2CharSelStrcFirst) {
      D2CharSelStrc* pListTail;
      pListHead = D2Client::CharScreen::D2CharSelStrcFirst->pNext;
      pListTail = D2Client::CharScreen::D2CharSelStrcFirst;
      while (pListHead) {
        pListTail = pListTail->pNext;
        pListHead = pListTail->pNext;
      }

      pListTail->pNext = pCharSel;
      pListHead = D2Client::CharScreen::D2CharSelStrcFirst;
    }

    D2Client::CharScreen::D2CharSelStrcFirst = pListHead;
    D2Client::CharScreen::TotalCurrentChars++;
    DRAW_LocalCharsInSelectionScreen0();
    return 1;
}

