    nCharacterSelectionIndex = 1;
    D2Client::CharScreen::TotalCurrentChars = 0;
    g_nCharSelNavigationIndex = 0;
    D2Client::CharScreen::nSelectedCharIndex = 0;
    gnCharSelSelectedIndex = 0;
